import json,hashlib
from pathlib import Path
j=json.load(open('/data/raw/two-host-live-g70.json'));c=json.load(open('/data/raw/g70-native-control.json'))
assert j['run_id']==c['run_id']=='40293205084' and j['source_commit']==c['source_commit']=='11e25be92e33c76a23a6469cbbacbee33fb8d117'
assert j['error'] is None and j['cleanup'] is True and j['firewall_verified'] is True and c['passed'] is True
assert len(c['rows'])==12 and all(r['passed'] for r in c['rows'])
rows=j['request_value_audit']['rows'];cdn=[r for r in rows if r['host']=='level3.blizzard.com'];unknown=[r for r in cdn if not r['public_download_path']['whole_path_exactly_in_independent_public_reference']]
t=j['unknown_key_origin_trace'];assert len(t['targets'])==len(unknown)==1
x=t['targets'][0];prior=[o for o in x['occurrences'] if o['preceded_request_observation']];assert prior and all(o['source_kind']=='version_TLS_plaintext' for o in prior)
# Independent count directly against the serialized raw hierarchy, without reusing prior.
check=sum(1 for target in j['unknown_key_origin_trace']['targets'] for o in target['occurrences'] if o['source_kind']=='version_TLS_plaintext' and o['preceded_request_observation'] is True)
assert check==len(prior)==3
assert x['observation_count']==1 and any(f['module']=='Agent' for f in x['request_frames'])
assert not x['public_origin_proven'] and not x['derivation_proven'] and not t['coverage_complete']
assert t['source_counts'].get('evicted_chunks',0)==0 and not j['hook_counts'].get('origin_gap_source_byte_cap',0)
trans=j['accepted_write_transport_audit'];assert trans['accounting_reconciles'] and not trans['cap_hit']
assert sum(v for k,v in trans['counts'].items() if k.endswith('_record_bytes'))+trans['counts']['HTTP1_candidate_bytes']==trans['accepted_API_input_bytes']==j['hook_counts']['peer_selected_target_IP_bytes']
ranges=[r['public_download_path']['range_semantics'] for r in cdn if r['range_present']]
Path('/data/analysis/g70-request-rows.json').write_text(json.dumps(rows))
sha=hashlib.sha256(Path('/data/raw/g70-artifact.zip').read_bytes()).hexdigest();assert sha=='c0004c5c26504e4c983d1492847ac82d4991f5fcd3eceb986ca70362b17d8a21'
e={'run_id':j['run_id'],'source_commit':j['source_commit'],'artifact_sha256':sha,'initial_preflight_failed_run':'40292278079','initial_target_executed':False,'initial_cause':'fixed hash rejected Windows working-tree bytes; all local base Git blob SHAs matched source commit; git-show byte materialization fixed it; exact original byte difference was not logged','CDN_API_observation_rows':len(cdn),'exact_public_path_matches':len(cdn)-len(unknown),'unknown_path_rows':len(unknown),'unknown_target_observations':x['observation_count'],'prior_version_plaintext_occurrence_events':len(prior),'events_are_not_distinct_responses':True,'unknown_key_still_not_independently_public':True,'causal_derivation_proven':False,'unknown_origin_trace':t,'gaps':{k:v for k,v in j['hook_counts'].items() if k.startswith('origin_gap_')},'full_trace_eviction_count':t['source_counts'].get('evicted_chunks',0),'source_byte_cap_hit':bool(j['hook_counts'].get('origin_gap_source_byte_cap',0)),'native_controls_passed':len(c['rows']),'tests_discovered':90,'Windows_tests_passed':90,'redacted_API_rows':len(rows),'redacted_duplicate_rows_kept':len(rows)-len({json.dumps(r,sort_keys=True) for r in rows}),'Linux_native_Windows_test_skipped':1,'observation_seconds':j['observed_seconds'],'cleanup':j['cleanup'],'firewall_verified':j['firewall_verified'],'TLS_certificate_cache_online_and_offline_passed':j['certificate_cache_online']['successful'] and j['certificate_cache_offline']['successful'],'transport_audit':trans,'range_rows':len(ranges),'range_exact_public_boundaries':sum(r['exact_public_boundary_match'] for r in ranges),'coverage_complete':j['coverage_complete'],'grain':'redacted API observations; repeated API rows retained, not unique network requests; provenance events may overlap','profiling_notes':'runtime has heterogeneous arrays, normalized to request_value_audit.rows; control constants/null failure_stage/error_type expected because one run and success, run_id treated as identifier not measure','comparison_plan':[{'finding':'The unmatched key occurs before its outgoing observation in decrypted input attributed to version server','population':'one unknown target observation, three potentially overlapping source events','unit':'exact ASCII lower-hex byte occurrence','disposition':'prose','reason':'semantic equality with no causal or time-series comparison'}]}
Path('/data/analysis/g70-evidence.json').write_text(json.dumps(e,ensure_ascii=False,indent=2))
print(json.dumps({k:e[k] for k in ['CDN_API_observation_rows','exact_public_path_matches','unknown_path_rows','prior_version_plaintext_occurrence_events','native_controls_passed','range_rows','range_exact_public_boundaries','gaps','source_byte_cap_hit','full_trace_eviction_count']}))
